<template><q-page class="q-pa-sm"><div class="row items-center q-mb-sm"><div><div class="text-subtitle1 text-weight-bold">Configuración</div><div class="text-caption text-grey-7">Identidad y datos comerciales</div></div><q-space/><q-badge color="positive" label="Datos para ventas, compras e impresión"/></div><q-card flat bordered class="config-card"><q-form @submit="save"><q-card-section class="row q-col-gutter-md q-pa-md"><div class="col-12 col-sm-4 column items-center"><div class="logo-box" @click="logoInput?.pickFiles()"><img v-if="preview||form.logo_url" :src="preview||form.logo_url"/><q-icon v-else name="add_photo_alternate" size="42px" color="grey-5"/><div class="logo-overlay"><q-icon name="upload"/> Cambiar logo</div></div><q-file ref="logoInput" v-model="logoFile" accept="image/*" class="hidden" @update:model-value="previewLogo"/><div class="text-caption text-grey-6 q-mt-xs">PNG, JPG o WEBP · máximo 8 MB</div></div><div class="col-12 col-sm-8 row q-col-gutter-sm"><q-input v-model="form.nombre_empresa" dense outlined label="Nombre de la empresa *" class="col-12"><template #prepend><q-icon name="store"/></template></q-input><q-input v-model="form.nit" dense outlined label="NIT" class="col-12 col-sm-5"><template #prepend><q-icon name="badge"/></template></q-input><q-input v-model="form.telefono" dense outlined label="Teléfono" class="col-12 col-sm-7"><template #prepend><q-icon name="phone"/></template></q-input><q-input v-model="form.direccion" dense outlined label="Dirección" class="col-12"><template #prepend><q-icon name="location_on"/></template></q-input><div class="col-12"><div class="margin-box"><div class="row items-center no-wrap"><q-icon name="percent" size="20px" class="q-mr-sm"/><div class="col"><b>Margen por porcentaje</b><div class="text-caption text-grey-7">Calcula el precio de venta como costo + %, por bloque: todas las líneas de una compra o varios productos a la vez. Desactivado, el precio de venta se carga a mano.</div></div><q-toggle v-model="form.margen_activo" color="positive" :label="form.margen_activo?'Activado':'Desactivado'" left-label/></div><q-input v-if="form.margen_activo" v-model.number="form.margen_porcentaje" dense outlined type="number" min="0" step="0.5" label="Margen por defecto" suffix="%" class="q-mt-sm" style="max-width:220px" :hint="`Ej.: costo Bs 10 → venta Bs ${(10*(1+(Number(form.margen_porcentaje)||0)/100)).toFixed(2)}`"/></div></div><div class="col-12"><div class="preview-title">Vista previa</div><div class="company-preview row items-center no-wrap"><q-avatar rounded size="42px" color="white"><img v-if="preview||form.logo_url" :src="preview||form.logo_url"/><q-icon v-else name="storefront" color="primary"/></q-avatar><div class="q-ml-sm"><b>{{form.nombre_empresa||'Nombre de empresa'}}</b><div>{{form.direccion||'Dirección'}} · Tel. {{form.telefono||'—'}} <span v-if="form.nit">· NIT {{form.nit}}</span></div></div></div></div></div></q-card-section><q-separator/><q-card-actions align="right" class="q-pa-sm"><q-btn color="primary" unelevated icon="save" label="Guardar cambios" no-caps type="submit" :loading="saving"/></q-card-actions></q-form></q-card></q-page></template>
<script setup>import{getCurrentInstance,onMounted,reactive,ref}from'vue';const{proxy}=getCurrentInstance(),form=reactive({nombre_empresa:'',nit:'',direccion:'',telefono:'',logo:null,logo_url:null,margen_activo:true,margen_porcentaje:30}),saving=ref(false),logoFile=ref(null),preview=ref(''),logoInput=ref(null);const enrich=data=>({...data,logo_url:data.logo?`${proxy.$imgBase}/images/${data.logo}`:null});onMounted(()=>proxy.$axios.get('/configuracion').then(r=>Object.assign(form,enrich(r.data))));function previewLogo(file){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=file?URL.createObjectURL(file):''}async function save(){if(!form.nombre_empresa)return proxy.$alert.error('Ingrese el nombre de la empresa');saving.value=true;try{let data=(await proxy.$axios.put('/configuracion',form)).data;if(logoFile.value){const fd=new FormData();fd.append('logo',logoFile.value);data=(await proxy.$axios.post('/configuracion/logo',fd)).data}Object.assign(form,enrich(data));localStorage.setItem('empresaBuonPrezzo',JSON.stringify(form));logoFile.value=null;proxy.$alert.success('Configuración guardada')}catch(e){proxy.$alert.error(Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||'No se pudo guardar')}finally{saving.value=false}}</script>
<style scoped>.config-card{max-width:780px}.logo-box{position:relative;width:150px;height:115px;border:2px dashed #F5D94E;border-radius:12px;background:#FFFDF0;display:flex;align-items:center;justify-content:center;overflow:hidden;cursor:pointer}.logo-box img{width:100%;height:100%;object-fit:contain}.logo-overlay{position:absolute;inset:auto 0 0;background:rgba(120,12,12,.75);color:white;text-align:center;padding:4px;font-size:11px}.margin-box{border:1px solid #e0e0e0;border-radius:10px;padding:10px;background:#fafafa}.preview-title{font-size:10px;color:#777;margin-bottom:3px}.company-preview{border:1px solid #FFF3B0;background:#FFFDF0;border-radius:10px;padding:7px;color:#5d4037;font-size:11px}</style>
